public void enableButtons()
{
    next enableButtons();

    TAMRebateDealGUPExtensionHelper::setUpGUPUIForRebateDealFormDeactiveButton(this, TAMRebateDeal);
}

public void customizeMenuOptions(OfficeMenuOptions _menuOptions)
{
    next customizeMenuOptions(_menuOptions);

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        _menuOptions.dataEntityOptions().addEnd(OfficeMenuDataEntityOptions::construct(tableStr(GUPRebateAmortizationScheduleDetailEntity)));
    }
}

[FormControlEventHandler(formControlStr(TAMRebateDeal, TabPageDetails), FormControlEventType::PageActivated)]
