[FormDataSourceEventHandler(formDataSourceStr(TAMRebateDeal, TAMRebateTable), FormDataSourceEventType::InitValue)]
public static void TAMRebateTable_OnInitValue(FormDataSource _sender, FormDataSourceEventArgs _e)
{
    if (TAMRebateDealGUPExtensionHelper::shouldShowGUPUI(_sender.formRun()))
    {
        TAMRebateTable rebateTable = _sender.cursor();
        rebateTable.RebateId = NumberSeq::newGetNum(TAMRebateParameters::numRefRebateId(), false).num();
        rebateTable.ItemCode = TableGroupAll::All;
        rebateTable.AccountCode = TableGroupAll::All;

        TAMRebateDeal rebateDeal = TAMRebateDeal::find(rebateTable.RebateDeal);
        if (rebateDeal.RebateReconciliation == TAMRebateReconciliation::Line)
        {
            rebateTable.RebatePostingId = TAMRebateDeal::find(rebateTable.RebateDeal).RebatePostingId;
        }
    }
}

[FormDataSourceEventHandler(formDataSourceStr(TAMRebateDeal, TAMRebateTable), FormDataSourceEventType::Created)]
public static void TAMRebateTable_OnCreated(FormDataSource _sender, FormDataSourceEventArgs _e)
{
    if (TAMRebateDealGUPExtensionHelper::shouldShowGUPUI(_sender.formRun()))
    {
        TAMRebateTable rebateTable = _sender.cursor();
        FormRun formRun = _sender.formRun();

        _sender.write();

        Args args = new Args();
        args.record(rebateTable);
        args.parmEnum(FormDataSourceEventType::Created);
        args.parmEnumType(enumNum(FormDataSourceEventType));

        new MenuFunction(menuItemDisplayStr(GUPPriceRebatePriceAttributeGroupEdit), MenuItemType::Display).run(args);
    }
}

[FormControlEventHandler(formControlStr(TAMRebateDeal, TAMRebateDeal_Recipient), FormControlEventType::Lookup)]
public static void TAMRebateDeal_Recipient_OnLookup(FormControl _sender, FormControlEventArgs _e)
{
    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        TAMRebateDeal rebateDeal = _sender.formRun().dataSource(tableStr(TAMRebateDeal)).cursor();

        switch (rebateDeal.ModuleInventCustVend)
        {
            case ModuleInventCustVend::Cust:
                CustTable::lookupCustomer(_sender);
                break;
            case ModuleInventCustVend::Vend:
                VendTable::lookupVendor(_sender);
                break;
        }
        FormControlCancelableSuperEventArgs ce = _e as FormControlCancelableSuperEventArgs;
        ce.CancelSuperCall();
    }
}
